def find_kth_neq_number(K: int) -> int:
    def is_neq_number(n: int) -> bool:
        s = str(n)
        return all(s[i] != s[i + 1] for i in range(len(s) - 1))

    count = 0
    num = 0
    while count < K:
        num += 1
        if is_neq_number(num):
            count += 1
    return num
